import {profile,save,SPECIES,PATROL_IDS,ZONES,TICKETS,SHOP,owned,rank,maxHP,nextLevelXP,patrolCount,zoneOpen,oakOpen,chooseStarter,rest,setTeam,train,buy,claimTicket,scout,makeUnit,startBattle,battleTurn,rewardBattle} from './world.js';
import {artHTML} from './art.js';
import {startEncounter,currentEncounter,leaveEncounter,openCatchLog,playSound} from './game.js';

const $=id=>document.getElementById(id);
let tab='trail',selectedZone=Math.max(0,ZONES.findIndex(z=>z.id===profile.zone)),battle=null,battleBusy=false,toastTimer=null,pendingResult='',championPending=false;
if(!zoneOpen(selectedZone))selectedZone=0;
const typeTag=id=>`<span class="mini-tag type-tag" style="--type:${SPECIES[id].color}">${SPECIES[id].type}</span>`;
const action=(name,arg='')=>`data-action="${name}" data-arg="${arg}"`;
const healthy=()=>profile.team.some(id=>owned(id)?.hp>0);

function toast(text){$('world-toast').textContent=text;$('world-toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('world-toast').classList.remove('visible'),2800);}
function setScreen(name){clearTimeout(toastTimer);$('world-toast').classList.remove('visible');$('game').dataset.screen=name;$('world-screen').hidden=name!=='world';$('battle-screen').hidden=name!=='battle';}
function toWorld(next='trail'){leaveEncounter();setScreen('world');tab=next;render(true);if(!profile.started)showStarter();}
function openEncounter(unit,weakened=false){if(!profile.started)return showStarter();setScreen('encounter');startEncounter(unit.species,unit.level,{weakened});}

function trailHTML(){
  const zone=ZONES[selectedZone],open=zoneOpen(selectedZone),done=profile.badges.includes(zone.id);
  return `<div class="trail-view"><div class="trail-intro"><div><h2>${profile.champion?'Woodland champion':'Your next trail'}</h2><p>${patrolCount(profile)} of 8 critters · ${profile.badges.length} of 3 badges · Scout rank ${rank(profile)}</p></div><div class="trail-progress" aria-label="${profile.badges.length} badges">${ZONES.map(z=>`<span class="${profile.badges.includes(z.id)?'earned':''}" title="${z.badge}">${z.symbol}</span>`).join('')}</div></div>
  <div class="trail-map"><div class="map-wash"></div><span class="map-label">The Gilwell woodland</span>${ZONES.map((z,i)=>`<button class="map-node ${i===selectedZone?'selected':''} ${zoneOpen(i)?'':'locked'}" style="left:${z.position[0]}%;top:${z.position[1]}%" ${action('zone',i)} aria-label="${z.name}${zoneOpen(i)?'':', locked'}" aria-pressed="${i===selectedZone}"><span class="node-symbol">${zoneOpen(i)?profile.badges.includes(z.id)?'✓':z.symbol:'⌑'}</span><span class="node-label">${z.name}</span></button>`).join('')}
  <button class="map-node oak ${oakOpen()?'':'locked'}" style="left:65%;top:12%" ${action('oak')} aria-label="Great Oak, ${oakOpen()?'PartyPoss encounter':'collect 8 critters and 3 badges to unlock'}"><span class="node-symbol">✦</span><span class="node-label">Great Oak</span></button><button class="map-camp" ${action('camp')}>⌂ Base camp</button></div>
  <section class="zone-panel"><div class="zone-heading"><h2>${zone.name}</h2><span>Lv ${zone.level}–${zone.level+2}</span></div><div class="zone-line">${zone.pool.map(id=>artHTML(id)).join('')}<p>${done?`${zone.badge} badge earned`:zone.description}</p></div><div class="zone-actions"><button class="wood-button" ${action('explore')} ${open?'':'disabled'}>Explore the trail <span aria-hidden="true">→</span></button><button class="wood-button secondary" ${action('trial')} ${open?'':'disabled'}>${done?'Replay trial':'Challenge trial'}</button></div></section></div>`;
}

function healthHTML(unit){return `<div class="health-track" role="meter" aria-label="${SPECIES[unit.species].name} health" aria-valuemin="0" aria-valuemax="${maxHP(unit)}" aria-valuenow="${unit.hp}"><span style="width:${unit.hp/maxHP(unit)*100}%;${unit.hp/maxHP(unit)<.3?'background:#d78b68':''}"></span></div><div class="health-label"><span>${unit.hp} / ${maxHP(unit)} HP</span><span>${unit.level<25?`${Math.floor(unit.exp)} / ${nextLevelXP(unit)} XP`:'Max level'}</span></div>`;}
function patrolHTML(){return `<div class="page-content"><h2 class="page-title">Your patrol</h2><p class="page-subtitle">Three companions. One trail. Pick a lead, train your team, and look after each other.</p><div class="patrol-summary"><span><strong>${profile.team.length} / 3</strong> in your active patrol</span><button class="wood-button small" ${action('rest')}>Rest for free</button></div>${[...profile.roster].sort((a,b)=>profile.team.includes(b.species)-profile.team.includes(a.species)).map(unit=>{const id=unit.species,s=SPECIES[id],inTeam=profile.team.includes(id);return `<article class="patrol-card">${artHTML(id)}<div><div class="unit-heading"><h3>${s.name}</h3><span>Lv ${unit.level}</span></div>${healthHTML(unit)}<div class="unit-actions"><button class="${inTeam?'active':''}" ${action('team',id)} ${!inTeam&&profile.team.length>=3?'disabled':''}>${inTeam?'✓ In patrol':'Add to patrol'}</button>${inTeam?`<button ${action('lead',id)} ${profile.team[0]===id?'disabled':''}>${profile.team[0]===id?'Lead':'Make lead'}</button>`:''}<button ${action('train',id)} ${unit.level>=25||profile.coins<30+unit.level*5?'disabled':''}>Train ◈ ${30+unit.level*5}</button><button ${action('detail',id)} aria-label="Details for ${s.name}">ⓘ</button></div></div></article>`;}).join('')}<p class="small-note">Duplicate catches and battle wins train your patrol too. Resting restores everyone’s health.</p></div>`;}
function guideHTML(){return `<div class="page-content"><h2 class="page-title">The field guide</h2><p class="page-subtitle">${patrolCount(profile)} of 8 patrol critters found${owned('partyposs')?' · PartyPoss discovered':''}. Tap a critter for its moves and habitat.</p><div class="guide-grid">${Object.entries(SPECIES).map(([id,s])=>`<button class="guide-card ${id==='partyposs'?'special':''}" ${action('detail',id)}><span class="dex-number">${s.number}</span>${artHTML(id,owned(id)?'':'unknown')}<strong>${s.name}</strong><small>${owned(id)?`Lv ${owned(id).level} · ${s.type}`:'Not found yet'}</small></button>`).join('')}</div><p class="guide-footer">Beaver · Bobwhite · Eagle · Fox · Owl · Bear · Buffalo · Antelope. Eight woodland animals, each with a little magic.</p><button class="wood-button secondary full" style="margin-top:18px" ${action('log')}>Open catch log</button></div>`;}
function ticketsHTML(){return `<div class="page-content"><h2 class="page-title">Work your ticket</h2><p class="page-subtitle">Small steps make a great adventure. Finish a task, then collect your trail supplies.</p><div class="badges-row">${ZONES.map(z=>`<div class="badge-token ${profile.badges.includes(z.id)?'earned':''}"><strong>${z.symbol}</strong>${z.badge}</div>`).join('')}</div>${TICKETS.map(t=>{const value=Math.min(t.progress(profile),t.goal),done=profile.claimed.includes(t.id);return `<article class="ticket-card ${done?'complete':''}"><h3>${t.name}</h3><p>${t.detail}</p><div class="health-track"><span style="width:${value/t.goal*100}%"></span></div><div class="ticket-footer"><span>${value} / ${t.goal} · ◈ ${t.reward}</span><button class="wood-button small" ${action('claim',t.id)} ${done||value<t.goal?'disabled':''}>${done?'✓ Claimed':'Claim reward'}</button></div></article>`;}).join('')}<p class="small-note">Every ticket also rewards 3 berries and an Ultra Ball. All eight patrol critters and all three badges open the Great Oak.</p>${profile.champion?'<div class="camp-hero"><h2>Woodland champion</h2><p>Your patrol is complete, your badges are earned, and PartyPoss is part of the family. The trails are always open for another adventure.</p></div>':''}</div>`;}
function campHTML(){return `<div class="page-content"><div class="camp-hero"><span class="camp-star" aria-hidden="true">✦</span><h2>Back at base camp.</h2><p>A warm welcome, a little rest, and everything you need for the next trail.</p><button class="wood-button gold" ${action('rest')}>Rest your patrol · Free</button></div><div class="section-line"><h3>Trail supplies</h3><span>◈ ${profile.coins} coins</span></div>${Object.entries(SHOP).map(([key,item])=>`<article class="shop-row"><span class="shop-icon" aria-hidden="true">${item.icon}</span><div class="shop-copy"><h3>${item.name} ×${item.amount}</h3><p>${profile[key]} in your pack</p></div><button class="wood-button small secondary" ${action('buy',key)} ${profile.coins<item.price||profile[key]>99-item.amount?'disabled':''}>◈ ${item.price}</button></article>`).join('')}<p class="small-note">Regular Poké Balls are unlimited. Catching critters, winning battles, and finishing tickets earn coins.</p><div class="camp-bottom"><button ${action('help')}>How to play</button><button ${action('sound')}>Sound ${profile.sound?'on':'off'}</button><button ${action('log')}>Catch log</button></div><p class="small-note">Saved on this device. An independent fan game featuring woodland critters and PartyPoss.</p></div>`;}

function render(reset=false){const scroll=reset?0:$('world-content').scrollTop;$('coin-count').textContent=profile.coins;document.querySelectorAll('[data-tab]').forEach(b=>{if(b.dataset.tab===tab)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$('world-content').innerHTML=tab==='trail'?trailHTML():tab==='patrol'?patrolHTML():tab==='guide'?guideHTML():tab==='tickets'?ticketsHTML():campHTML();$('world-content').scrollTop=scroll;}
function showStarter(){if(profile.started)return;$('starter-options').innerHTML=['beaver','bobwhite','fox'].map(id=>`<button class="starter-choice" ${action('starter',id)}>${artHTML(id)}<strong>${SPECIES[id].name}</strong><small>${SPECIES[id].type} · Lv 5</small></button>`).join('');if(!$('starter-dialog').open)$('starter-dialog').showModal();}
$('starter-dialog').addEventListener('cancel',event=>{if(!profile.started)event.preventDefault();});

function showDetail(id){const s=SPECIES[id];if(!s)return;const unit=owned(id),zone=ZONES.find(z=>z.pool.includes(id));$('detail-dialog').innerHTML=`<button class="close-button" ${action('close','detail-dialog')} aria-label="Close critter details">×</button><span class="eyebrow">FIELD GUIDE / ${s.number}</span>${artHTML(id)}<h2>${s.name} ${typeTag(id)}</h2><p>${s.description}</p>${unit?`<div class="detail-stats"><div><strong>${unit.level}</strong><span>Level</span></div><div><strong>${unit.hp}/${maxHP(unit)}</strong><span>Health</span></div><div><strong>${profile.team.includes(id)?'Yes':'No'}</strong><span>In patrol</span></div></div>`:`<p class="small-note">Find ${s.name} ${id==='partyposs'?'at the Great Oak after collecting all 8 patrol critters and earning 3 badges':`in ${zone?.name}`}.</p>`}<div class="detail-move"><strong>${s.move}</strong><p>Basic move · builds 1 energy</p></div><div class="detail-move"><strong>${s.special}</strong><p>Special move · costs 3 energy${id==='bear'?' · restores 20% health':''}${id==='partyposs'?' · the original Maui Wali magic':''}</p></div><button class="wood-button full" ${action('close','detail-dialog')}>Back to the field guide</button>`;$('detail-dialog').showModal();}

function enterBattle(kind,unit=null){if(!healthy()){toast('Your patrol needs a rest. Camp heals everyone for free.');toWorld('camp');return;}const zone=ZONES[selectedZone];const next=startBattle(kind,zone.id,unit);if(!next){toast('That trail is still locked.');return;}leaveEncounter();battle=next;battleBusy=false;setScreen('battle');renderBattle();playSound([294,392,494],.09);}
function battleHP(unit,side){return `<div class="battle-health ${side}"><div class="unit-heading"><h3>${SPECIES[unit.species].name}</h3><span>Lv ${unit.level}</span></div>${healthHTML(unit)}</div>`;}
function renderBattle(){if(!battle)return;const ally=owned(battle.active),enemy=battle.enemy,s=SPECIES[ally.species],zone=ZONES.find(z=>z.id===battle.zoneId);$('battle-screen').innerHTML=`<header class="battle-top"><strong>${battle.kind==='trial'?zone.trial:'Wild encounter'}</strong><button class="retreat-button" ${action('retreat')}>Retreat</button></header><div class="battle-arena">${battleHP(enemy,'enemy')}<div class="battle-sprite enemy">${artHTML(enemy.species)}</div><div class="battle-sprite ally">${artHTML(ally.species)}</div>${battleHP(ally,'ally')}</div><div class="battle-log" aria-live="polite">${battle.log}</div><div class="battle-moves"><button class="battle-move" ${action('battle','attack')} ${battleBusy?'disabled':''}><strong>${s.move}</strong><small>${s.type} · +1 energy</small></button><button class="battle-move special" ${action('battle','special')} ${battleBusy||battle.energy<3?'disabled':''}><strong>${s.special}</strong><small>Special · ${battle.energy}/3 energy</small></button><button class="battle-move" ${action('battle','guard')} ${battleBusy?'disabled':''}><strong>Guard & recover</strong><small>Less damage · +1 energy</small></button><button class="battle-move" ${action('battle','potion')} ${battleBusy||profile.potions<1||ally.hp>=maxHP(ally)?'disabled':''}><strong>Trail tonic ×${profile.potions}</strong><small>Restore 60% HP</small></button></div><div class="battle-patrol"><span>SWAP</span>${profile.team.map(id=>`<button class="${id===battle.active?'active':''}" ${action('battle',`swap:${id}`)} ${battleBusy||id===battle.active||owned(id).hp<=0?'disabled':''} aria-label="Switch to ${SPECIES[id].name}, ${owned(id).hp} health">${artHTML(id)}<span>${owned(id).hp>0?SPECIES[id].name:'Resting'}</span></button>`).join('')}</div><div class="battle-special-banner" aria-hidden="true"></div><div class="battle-magic" aria-hidden="true"><span class="magic-ring"></span><span class="magic-ring purple"></span>${Array.from({length:25},(_,i)=>`<span class="magic-particle ${i%4===0?'flower':i%3===0?'sparkle':''}" style="--x:${8+(i*37)%85}%;--y:${8+(i*23)%82}%;--delay:${i%5*.05}s"></span>`).join('')}</div>`;}

async function takeTurn(move){if(!battle||battleBusy||battle.status!=='active')return;const activeId=battle.active;battleBusy=true;const result=battleTurn(battle,move);if(!result.ok){battleBusy=false;return;}save();renderBattle();const panel=$('battle-screen');panel.querySelector('.battle-sprite.enemy').classList.add('hit');panel.querySelector('.battle-sprite.ally').classList.add('strike');const special=move==='special';if(special){panel.classList.add('is-special');panel.querySelector('.battle-special-banner').textContent=`${result.move}!`;if(activeId==='partyposs'){panel.classList.add('is-maui');const sprite=panel.querySelector('.battle-sprite.ally .critter-art');sprite.className='critter-art single';sprite.innerHTML='<img src="./assets/partyposs-attack.webp" alt="">';}playSound(special?[392,494,587,784]:[392,520],.12,'triangle');}else playSound([330,260],.06);
  await new Promise(resolve=>setTimeout(resolve,special?1650:550));panel.classList.remove('is-special','is-maui');battleBusy=false;if(!battle)return;if(battle.status==='active')renderBattle();else finishBattle();}

function finishBattle(){const won=battle.status==='won',zone=ZONES.find(z=>z.id===battle.zoneId);const reward=won?rewardBattle(battle):null;save();pendingResult='';const trial=battle.kind==='trial';$('battle-result').innerHTML=`${won&&trial?`<span class="victory-token">${zone.symbol}</span>`:artHTML(won?battle.queue[0].species:battle.active,'battle-result-art')}<span class="eyebrow">${won?trial?'A TRAIL WELL TRAVELLED':'A NEW FRIEND IS CLOSE':'EVERY PATROL NEEDS A REST'}</span><h2 class="battle-result-title">${won?trial?`${zone.badge} earned!`:'Well played!':'Back to camp.'}</h2><p>${won?trial?reward.first?'You passed the trial. The next trail is open.':'Another great day on the trail. Your patrol grew stronger.':`${SPECIES[battle.queue[0].species].name} is tired and easier to catch now.`:'Your critters gave it their best. Rest for free and try again with a different lead or a few more levels.'}</p>${reward?`<p class="result-summary">+${reward.xp} XP · +${reward.coins} coins${reward.first?' · +3 tonics · +3 Ultra Balls':''}</p>`:''}<button class="wood-button full" ${action(won?(trial?'result-trail':'result-catch'):'result-rest')}>${won?(trial?'Back to the trail':'Try the boosted catch'):'Rest at base camp'} <span aria-hidden="true">→</span></button>`;$('battle-result').showModal();playSound(won?[523,659,784,1047]:[392,330,262],.13);}
$('battle-result').addEventListener('close',()=>{const last=battle;battle=null;battleBusy=false;if(pendingResult==='catch'&&last){openEncounter(last.queue[0],true);}else if(pendingResult==='rest'){rest();save();toWorld('camp');}else{if(last?.kind==='trial'&&last.status==='won'){const index=ZONES.findIndex(z=>z.id===last.zoneId);selectedZone=Math.min(index+1,2);}toWorld();}pendingResult='';});

function showChampion(){$('detail-dialog').innerHTML=`<span class="victory-token">✦</span><span class="eyebrow">THE WHOLE PATROL, TOGETHER</span><h2>Woodland champion!</h2>${artHTML('partyposs')}<p>Eight patrol critters. Three trail badges. And one very special birthday friend. You completed the Woodland adventure.</p><p class="result-summary">Your patrol and progress are saved. Keep training, revisit the trials, and let PartyPoss bring Maui Wali into battle.</p><button class="wood-button full" ${action('close','detail-dialog')}>Keep exploring</button>`;$('detail-dialog').showModal();}

document.addEventListener('click',event=>{
  const button=event.target.closest('[data-action]');if(!button||button.disabled)return;
  const name=button.dataset.action,arg=button.dataset.arg;
  if(name==='starter'){if(chooseStarter(arg)){save();$('starter-dialog').close();toast(`${SPECIES[arg].name} joined your patrol. The lake trail is open!`);}return;}
  if(name==='close'){$(arg)?.close();return;}
  if(name==='camp'){toWorld('camp');return;}
  if(name==='zone'){const index=Number(arg);if(!zoneOpen(index)){toast(`Earn the ${ZONES[index-1].badge} badge to open this trail.`);return;}selectedZone=index;profile.zone=ZONES[index].id;save();return;}
  if(name==='explore'){const unit=scout(ZONES[selectedZone].id);if(unit){save();openEncounter(unit);}return;}
  if(name==='oak'){if(!oakOpen()){toast('Collect all 8 patrol critters and earn 3 badges to open the Great Oak.');return;}openEncounter(makeUnit('partyposs',12));return;}
  if(name==='trial'){enterBattle('trial');return;}
  if(name==='rest'){rest();save();toast('Everyone is rested. Your patrol is ready!');playSound([440,554,659]);return;}
  if(name==='team'){if(!setTeam(arg))toast('Keep at least one critter in your patrol. Three is the maximum.');else save();return;}
  if(name==='lead'){if(profile.team.includes(arg)){profile.team=[arg,...profile.team.filter(id=>id!==arg)];save();toast(`${SPECIES[arg].name} is leading your patrol.`);}return;}
  if(name==='train'){if(train(arg)){save();toast(`${SPECIES[arg].name} reached level ${owned(arg).level}!`);playSound([523,659,784]);}return;}
  if(name==='buy'){if(buy(arg)){save();toast(`${SHOP[arg].name} ×${SHOP[arg].amount} added to your pack.`);}return;}
  if(name==='claim'){if(claimTicket(arg)){save();toast('Ticket complete! Coins, berries, and an Ultra Ball added.');playSound([523,659,784]);}return;}
  if(name==='detail'){showDetail(arg);return;}
  if(name==='help'){$('help-dialog').showModal();return;}
  if(name==='sound'){profile.sound=!profile.sound;save();playSound([523,659]);return;}
  if(name==='log'){openCatchLog();return;}
  if(name==='battle'){void takeTurn(arg);return;}
  if(name==='retreat'){if(battleBusy)return;battle=null;toWorld();toast('Back on the trail. Your patrol keeps its experience.');return;}
  if(name.startsWith('result-')){pendingResult=name.slice(7);$('battle-result').close();}
});
$('camp-button').addEventListener('click',()=>toWorld('camp'));
document.querySelectorAll('[data-tab]').forEach(button=>button.addEventListener('click',()=>{tab=button.dataset.tab;render(true);}));
$('wild-battle-button').addEventListener('click',()=>enterBattle('wild',makeUnit(currentEncounter().species,currentEncounter().level)));
window.addEventListener('profilechange',()=>render());
window.addEventListener('woodlandready',()=>{if(!profile.started)showStarter();});
window.addEventListener('crittercaught',event=>{if(event.detail.champion)championPending=true;});
window.addEventListener('encounterdone',()=>{toWorld();if(championPending){championPending=false;showChampion();}});
render();if($('game').dataset.phase!=='loading'&&!profile.started)showStarter();
